try { const saved = JSON.parse(localStorage.getItem(KEY)); if (saved && typeof saved === 'object') state = { read: Array.isArray(saved.read) ? saved.read.filter(Number.isInteger) : [], pinned: Array.isArray(saved.pinned) ? saved.pinned.filter(Number.isInteger) : [], notes: typeof saved.notes === 'string' ? saved.notes : '', solved: saved.solved === true }; } catch {}
